await sql.unsafe("INSERT INTO jarvis_wallet_routes(address,label,is_primary) VALUES ('bc1qdmzr4m78ulj2saa97vg9kmpzuxu3477gvc2rct','Owner wallet · primary',TRUE) ON CONFLICT(address) DO UPDATE SET label=EXCLUDED.label,is_primary=EXCLUDED.is_primary");
