await sql.unsafe("INSERT INTO jarvis_wallet_routes(address,label,is_primary) VALUES ($1,'Blockstream · active BTC receive',TRUE) ON CONFLICT(address) DO UPDATE SET label=EXCLUDED.label,is_primary=TRUE",[env.BTC_RECEIVE_ADDRESS||"bc1qdmzr4m78ulj2saa97vg9kmpzuxu3477gvc2rct"]);
await sql.unsafe("DELETE FROM jarvis_wallet_routes WHERE address<>$1",[env.BTC_RECEIVE_ADDRESS||"bc1qdmzr4m78ulj2saa97vg9kmpzuxu3477gvc2rct"]);
