function freeGoodHttps(value){
 if(typeof value!=="string"||value.length>500)return "";
 try{
  const url=new URL(value.trim());
  const host=url.hostname.toLowerCase();
  if(url.protocol!=="https:"||url.username||url.password||url.port||!host.includes(".")||host.endsWith(".local")||host.endsWith(".internal")||/^\d/.test(host))return "";
  return url.href;
 }catch{return ""}
}
function freeGoodQuote(input){
 const fields=["market","pickup","inbound","shipping","fees"];
 if(!fields.every(key=>Number.isSafeInteger(input[key])&&input[key]>=0&&input[key]<=10000000)||![20,30].includes(input.discount))return null;
 const target=Math.floor(input.market*(100-input.discount)/100);
 const cost=input.pickup+input.inbound+input.shipping+input.fees;
 return {target,cost,margin:target-cost};
}

